import io.restassured.builder.RequestSpecBuilder;
import io.restassured.specification.RequestSpecification;

class WspolnaSpecyfikacja {

    static RequestSpecification zbudujSpec(int port) {
        return new RequestSpecBuilder()
            .setBaseUri("http://localhost")
            .setPort(port)
            .setContentType("application/json")
            .build();
    }

    void przykladUzycia(RequestSpecification spec) {
        given()
            .spec(spec)
            .when()
                .get("/api/zadania")
            .then()
                .statusCode(200);
    }
}

@Test
void usunieciaZadaniaBezTokenuOdrzucaneJako401() {
    given()
        .when()
            .delete("/api/zadania/1")
        .then()
            .statusCode(401);
}

@Test
void usuniecieZadaniaZWaznymTokenemDzialaPoprawnie() {
    String token = zdobadzTokenTestowegoUzytkownika();

    given()
        .header("Authorization", "Bearer " + token)
        .when()
            .delete("/api/zadania/1")
        .then()
            .statusCode(204);
}

